void write_row(int row, const char *name, int pid, int count, uint8 color) {
    char buf[80];
    int pos = 0;

    // 线程名
    const char *s = name;
    while (*s) buf[pos++] = *s++;
    buf[pos++] = '[';
    buf[pos++] = 'P';
    buf[pos++] = 'I';
    buf[pos++] = 'D';
    buf[pos++] = ':';

    // PID
    char tmp[12];
    itos(tmp, (uint32)pid, 10);
    for (int i = 0; tmp[i]; ++i) buf[pos++] = tmp[i];

    buf[pos++] = ']';
    buf[pos++] = ' ';
    buf[pos++] = 'c';
    buf[pos++] = 'n';
    buf[pos++] = 't';
    buf[pos++] = '=';

    // 计数器
    itos(tmp, (uint32)count, 10);
    for (int i = 0; tmp[i]; ++i) buf[pos++] = tmp[i];

    // 行末填充空格清除残留
    while (pos < 80) buf[pos++] = ' ';

    // 直接写入VGA显存对应行
    for (int i = 0; i < 80; ++i) {
        stdio.print(row, i, buf[i], color);
    }
}

